CREATE TABLE IF NOT EXISTS inv_stock_adjustments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, adjustment_ref VARCHAR(80) NOT NULL UNIQUE, adjustment_date DATE NOT NULL, branch_id INT UNSIGNED NOT NULL, warehouse_id INT UNSIGNED NOT NULL, opname_id INT UNSIGNED NULL, reason VARCHAR(255) NOT NULL, status ENUM('DRAFT','SUBMITTED','APPROVED','POSTED','REJECTED','CANCELLED') NOT NULL DEFAULT 'DRAFT', created_by INT UNSIGNED NOT NULL, approved_by INT UNSIGNED NULL, posted_by INT UNSIGNED NULL, approved_at DATETIME NULL, posted_at DATETIME NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_adj_b FOREIGN KEY(branch_id) REFERENCES branches(id), CONSTRAINT fk_adj_w FOREIGN KEY(warehouse_id) REFERENCES inv_warehouses(id), CONSTRAINT fk_adj_op FOREIGN KEY(opname_id) REFERENCES inv_stock_opnames(id), KEY ix_adj_scope(branch_id,warehouse_id,status,adjustment_date));
CREATE TABLE IF NOT EXISTS inv_stock_adjustment_lines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, adjustment_id INT UNSIGNED NOT NULL, item_id INT UNSIGNED NOT NULL, quantity_change DECIMAL(18,3) NOT NULL, reason VARCHAR(255) NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_adj_line_h FOREIGN KEY(adjustment_id) REFERENCES inv_stock_adjustments(id) ON DELETE CASCADE, CONSTRAINT fk_adj_line_i FOREIGN KEY(item_id) REFERENCES md_items(id), CHECK(quantity_change<>0));
INSERT IGNORE INTO permissions(code,name) VALUES ('inventory.adjustment.view','Lihat penyesuaian stok'),('inventory.adjustment.create','Buat penyesuaian stok'),('inventory.adjustment.update','Ubah penyesuaian stok'),('inventory.adjustment.submit','Kirim penyesuaian stok'),('inventory.adjustment.approve','Setujui penyesuaian stok'),('inventory.adjustment.reject','Tolak penyesuaian stok'),('inventory.adjustment.post','Posting penyesuaian stok'),('inventory.adjustment.cancel','Batalkan penyesuaian stok');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code='inventory.adjustment.view' WHERE r.name IN ('Owner','Finance');
